/* ============================================================
   GTA VI: PIXEL VICE — fan-made pixel tribute
   ============================================================ */
@font-face {
  font-family: 'PressStart';
  src: url('assets/press-start-2p.ttf') format('truetype');
  font-display: swap;
}
@font-face {
  font-family: 'Monoton';
  src: url('assets/monoton.ttf') format('truetype');
  font-display: swap;
}

:root {
  --pink: #ff2d95;
  --pink-hot: #ff5fb5;
  --cyan: #24e0ff;
  --purple: #7b2dff;
  --orange: #ff8a2b;
  --yellow: #ffd166;
  --green: #4ade80;
  --red: #ff3b3b;
  --ink: #07060d;
  --panel: rgba(9, 7, 18, 0.78);
  --line: rgba(255, 45, 149, 0.38);
  --pixel: 'PressStart', 'Courier New', monospace;
  --body: 'PressStart', 'Courier New', monospace;
  --neon: 0 0 6px rgba(255,45,149,.9), 0 0 18px rgba(255,45,149,.55), 0 0 42px rgba(255,45,149,.28);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #05040a;
  color: #fff;
  font-family: var(--pixel);
  -webkit-tap-highlight-color: transparent;
  -webkit-user-select: none;
  user-select: none;
  overscroll-behavior: none;
}

body { position: fixed; inset: 0; }

#app {
  position: fixed;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background:
    radial-gradient(ellipse at 50% 45%, #160b24 0%, #07060d 55%, #030208 100%);
  isolation: isolate;
}

#game {
  display: block;
  width: 640px;
  height: 360px;
  max-width: 100%;
  max-height: 100%;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  background: #0b0a18;
  touch-action: none;
  cursor: crosshair;
}

/* CRT / scanlines */
.crt {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 8;
  opacity: .22;
  background: repeating-linear-gradient(
    to bottom,
    rgba(0,0,0,.55) 0px,
    rgba(0,0,0,.55) 1px,
    transparent 1px,
    transparent 3px
  );
  mix-blend-mode: multiply;
}
.vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 9;
  background:
    radial-gradient(ellipse at center, transparent 52%, rgba(0,0,0,.42) 100%),
    linear-gradient(to bottom, rgba(0,0,0,.18), transparent 18%, transparent 82%, rgba(0,0,0,.28));
}

.hidden { display: none !important; }

/* ============================================================
   HUD
   ============================================================ */
#hud {
  position: absolute;
  inset: 0;
  z-index: 20;
  pointer-events: none;
  font-family: var(--pixel);
  text-shadow: 0 2px 0 rgba(0,0,0,.8);
}

.mission-card {
  position: absolute;
  top: max(14px, env(safe-area-inset-top));
  left: max(14px, env(safe-area-inset-left));
  width: min(300px, 38vw);
  padding: 10px 12px 9px;
  background: linear-gradient(135deg, rgba(20,8,30,.88), rgba(7,5,14,.72));
  border: 1px solid var(--line);
  border-left: 3px solid var(--pink);
  box-shadow: 0 0 18px rgba(255,45,149,.14), inset 0 0 24px rgba(123,45,255,.08);
  backdrop-filter: blur(5px);
}
.mission-top { display: flex; align-items: center; justify-content: space-between; }
.mission-tag {
  font-size: 7px;
  letter-spacing: 1px;
  color: var(--pink-hot);
}
.mission-dot { width: 6px; height: 6px; background: var(--pink); box-shadow: 0 0 8px var(--pink); animation: blink 1.2s steps(2) infinite; }
.mission-name {
  margin-top: 5px;
  font-size: 10px;
  color: #fff;
  letter-spacing: .5px;
  line-height: 1.4;
}
.mission-obj {
  margin-top: 5px;
  font-size: 7px;
  line-height: 1.7;
  color: #cdc6dd;
}
.mission-dist {
  margin-top: 6px;
  font-size: 8px;
  color: var(--yellow);
  letter-spacing: 1px;
}
.dist-arrow { color: var(--pink); }

.top-right {
  position: absolute;
  top: max(14px, env(safe-area-inset-top));
  right: max(14px, env(safe-area-inset-right));
  text-align: right;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 6px;
}
.clock-row { display: flex; align-items: center; gap: 6px; }
#clock {
  font-size: 9px;
  color: #d8d1e8;
  letter-spacing: 1px;
  margin-right: 2px;
  text-shadow: 0 0 8px rgba(36,224,255,.35);
}
.hud-btn {
  pointer-events: auto;
  width: 26px;
  height: 26px;
  padding: 0;
  display: grid;
  place-items: center;
  color: #cfc7e2;
  background: rgba(10,8,20,.7);
  border: 1px solid rgba(255,255,255,.16);
  font-family: var(--pixel);
  font-size: 8px;
  cursor: pointer;
}
.hud-btn:hover { color: #fff; border-color: var(--pink); box-shadow: 0 0 10px rgba(255,45,149,.4); }
.wanted {
  font-size: 14px;
  letter-spacing: 3px;
  color: rgba(255,255,255,.15);
  line-height: 1;
}
.wanted span { transition: color .2s, text-shadow .2s; }
.wanted span.on { color: var(--yellow); text-shadow: 0 0 8px rgba(255,209,102,.9), 0 0 18px rgba(255,138,43,.5); animation: wantedPulse .9s ease-in-out infinite alternate; }
.cash {
  font-size: clamp(14px, 2vw, 20px);
  color: var(--green);
  letter-spacing: 1px;
  text-shadow: 0 0 10px rgba(74,222,128,.45), 0 2px 0 #073b1c;
}

.bottom-left {
  position: absolute;
  left: max(14px, env(safe-area-inset-left));
  bottom: max(14px, env(safe-area-inset-bottom));
  width: min(240px, 34vw);
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.stat-row { display: grid; grid-template-columns: 44px 1fr 30px; align-items: center; gap: 6px; }
.stat-label { font-size: 6px; color: #bdb5cc; letter-spacing: .5px; }
.stat-track {
  height: 8px;
  background: rgba(0,0,0,.55);
  border: 1px solid rgba(255,255,255,.18);
  padding: 1px;
  box-shadow: inset 0 0 6px rgba(0,0,0,.8);
}
.stat-fill { height: 100%; width: 100%; transition: width .2s; }
.stat-fill.health { background: linear-gradient(90deg, #ff2d5e, #ff8a2b); box-shadow: 0 0 8px rgba(255,45,94,.45); }
.stat-fill.armor { background: linear-gradient(90deg, #24e0ff, #7b2dff); box-shadow: 0 0 8px rgba(36,224,255,.4); }
.stat-fill.car { background: linear-gradient(90deg, #ffd166, #ff8a2b); }
.stat-num { font-size: 7px; color: #fff; text-align: right; }
.car-health { display: grid; grid-template-columns: 44px 1fr 30px; gap: 6px; align-items: center; }

.bottom-right {
  position: absolute;
  right: max(14px, env(safe-area-inset-right));
  bottom: max(14px, env(safe-area-inset-bottom));
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 7px;
}
.weapon-box {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 9px;
  background: var(--panel);
  border: 1px solid rgba(255,255,255,.16);
}
.weapon-icon {
  width: 26px; height: 18px;
  display: grid; place-items: center;
  color: var(--yellow);
  border: 1px solid rgba(255,209,102,.4);
  font-size: 10px;
  background: rgba(255,209,102,.07);
}
.weapon-meta { display: flex; flex-direction: column; align-items: flex-end; gap: 3px; }
.weapon-meta span:first-child { font-size: 6px; color: #d8d1e8; }
.weapon-meta span:last-child { font-size: 8px; color: var(--yellow); }

.radar-wrap {
  position: relative;
  width: clamp(112px, 14vw, 152px);
  aspect-ratio: 1;
  border-radius: 50%;
  border: 2px solid rgba(255,45,149,.5);
  box-shadow: 0 0 18px rgba(255,45,149,.25), inset 0 0 18px rgba(0,0,0,.8);
  background: #080610;
  overflow: hidden;
}
#radar { width: 100%; height: 100%; display: block; image-rendering: pixelated; }
.radar-label {
  position: absolute;
  bottom: 5px; left: 0; right: 0;
  text-align: center;
  font-size: 5px;
  color: rgba(255,255,255,.5);
  letter-spacing: 1px;
}

.speedo {
  position: absolute;
  right: max(14px, env(safe-area-inset-right));
  bottom: calc(max(14px, env(safe-area-inset-bottom)) + clamp(150px, 18vw, 196px));
  width: 118px;
  padding: 6px 9px;
  background: var(--panel);
  border: 1px solid rgba(255,255,255,.14);
  text-align: right;
}
.speed-num { font-size: 14px; color: #fff; }
.speed-num small { font-size: 5px; color: var(--cyan); margin-left: 3px; }
.speed-bar { height: 4px; margin-top: 4px; background: rgba(255,255,255,.12); }
#speedFill { height: 100%; width: 0%; background: linear-gradient(90deg, var(--cyan), var(--pink)); }

.toasts {
  position: absolute;
  top: 20%;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 7px;
  width: min(520px, 82vw);
}
.toast {
  padding: 7px 12px;
  background: rgba(7,5,14,.88);
  border: 1px solid rgba(255,45,149,.35);
  font-size: 8px;
  line-height: 1.7;
  color: #fff;
  text-align: center;
  letter-spacing: .5px;
  animation: toastIn .22s steps(3) both;
  box-shadow: 0 0 16px rgba(0,0,0,.6);
}
.toast.gold { border-color: rgba(255,209,102,.6); color: var(--yellow); }
.toast.green { border-color: rgba(74,222,128,.6); color: var(--green); }
.toast.red { border-color: rgba(255,59,59,.7); color: #ff9b9b; }
.toast.out { animation: toastOut .3s steps(3) both; }

.desktop-hint {
  position: absolute;
  left: 50%;
  bottom: 10px;
  transform: translateX(-50%);
  font-family: var(--pixel);
  font-size: 6px;
  color: rgba(255,255,255,.38);
  letter-spacing: .3px;
  white-space: nowrap;
}
.desktop-hint b { color: rgba(255,255,255,.72); font-weight: normal; }

/* ============================================================
   MOBILE CONTROLS
   ============================================================ */
#touch { position: absolute; inset: 0; z-index: 22; pointer-events: none; }
body.touch #desktopHint { display: none; }
body.touch #touch { display: block; }
body.touch .radar-wrap { width: 108px; }
body.touch .bottom-left { width: 190px; }
body.touch .mission-card { width: min(250px, 52vw); }
body.touch .desktop-hint { display: none; }

.stick {
  position: absolute;
  left: max(18px, env(safe-area-inset-left));
  bottom: max(20px, env(safe-area-inset-bottom));
  width: 112px;
  height: 112px;
  pointer-events: auto;
  touch-action: none;
}
.stick-ring {
  position: absolute; inset: 0;
  border-radius: 50%;
  border: 2px solid rgba(255,255,255,.22);
  background: radial-gradient(circle, rgba(255,45,149,.1), rgba(8,6,16,.55) 70%);
  box-shadow: inset 0 0 20px rgba(0,0,0,.6), 0 0 18px rgba(255,45,149,.12);
}
.knob {
  position: absolute;
  left: 50%; top: 50%;
  width: 46px; height: 46px;
  margin: -23px 0 0 -23px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #ff8ec5, #ff2d95 55%, #7b2dff);
  border: 2px solid rgba(255,255,255,.6);
  box-shadow: 0 0 16px rgba(255,45,149,.6);
  transition: transform .05s linear;
}
.touch-actions {
  position: absolute;
  right: max(18px, env(safe-area-inset-right));
  bottom: max(22px, env(safe-area-inset-bottom));
  width: 190px;
  height: 170px;
  pointer-events: none;
}
.tbtn {
  position: absolute;
  pointer-events: auto;
  font-family: var(--pixel);
  font-size: 7px;
  color: #fff;
  border-radius: 50%;
  border: 2px solid rgba(255,255,255,.35);
  background: rgba(15,10,28,.68);
  box-shadow: inset 0 0 16px rgba(0,0,0,.55), 0 0 12px rgba(0,0,0,.35);
  touch-action: none;
}
.tbtn:active { transform: scale(.94); filter: brightness(1.25); }
.tbtn.fire {
  right: 0; bottom: 8px;
  width: 88px; height: 88px;
  background: radial-gradient(circle at 38% 32%, #ff7ab9, #ff2d95 55%, #a5105c);
  border-color: rgba(255,255,255,.6);
  box-shadow: 0 0 24px rgba(255,45,149,.5), inset 0 0 14px rgba(255,255,255,.2);
  font-size: 9px;
}
.tbtn.mid {
  right: 94px; bottom: 0;
  width: 64px; height: 64px;
  background: radial-gradient(circle at 38% 32%, #55e8ff, #24a9ff 55%, #1750a8);
  border-color: rgba(255,255,255,.55);
  font-size: 6px;
}
.tbtn.small {
  right: 28px; bottom: 104px;
  width: 58px; height: 58px;
  background: radial-gradient(circle at 38% 32%, #ffd88a, #ff8a2b 60%, #a34610);
  border-color: rgba(255,255,255,.5);
  font-size: 5px;
}

/* ============================================================
   OVERLAYS / MENUS
   ============================================================ */
.overlay {
  position: absolute;
  inset: 0;
  z-index: 40;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: max(16px, env(safe-area-inset-top)) max(16px, env(safe-area-inset-right)) max(16px, env(safe-area-inset-bottom)) max(16px, env(safe-area-inset-left));
}
.overlay.hidden { display: none !important; }

.btn {
