    const absorb = Math.min(player.armor, dmg * 0.65);
    player.armor -= absorb;
    dmg -= absorb;
  }
  player.health -= dmg;
  player.lastDamage = 0;
  player.damageFlash = .55;
  cam.shake = Math.max(cam.shake, 4);
  audio.hurt();
  if (player.health <= 0) {
    player.health = 0;
    die(source);
  }
