  player.health = 100;
  player.armor = 0;
  player.cash = Math.max(0, player.cash - 500);
  player.wanted = 0;
  player.invuln = 2.5;
  player.damageFlash = 0;
  player.inCar = null;
  player.fireCooldown = 0;
