      c.fillStyle = litA ? 'rgba(255,232,168,.85)' : '#2b2736'; c.fillRect(x + 1, wy, 2, 6);
      c.fillStyle = litB ? 'rgba(255,232,168,.7)' : '#2b2736'; c.fillRect(x + w - 3, wy, 2, 6);
    }

